import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";
import { destinationDetailsSchema, type DestinationDetails } from "./destination-details.js";
import { moneySchema, type Money } from "./money.js";
import { processingFeeSchema, type ProcessingFee } from "./processing-fee.js";

/**
 * Represents a refund of a payment made using Square. Contains information about the original
 * payment and the amount of money refunded.
 */
export type PaymentRefund = {
  /** The unique ID for this refund, generated by Square. */
  id: string;
  /**
   * The refund's status:
   * - `PENDING` - Awaiting approval.
   * - `COMPLETED` - Successfully completed.
   * - `REJECTED` - The refund was rejected.
   * - `FAILED` - An error occurred.
   */
  status?: string | null;
  /** The location ID associated with the payment this refund is attached to. */
  locationId?: string | null;
  /** Flag indicating whether or not the refund is linked to an existing payment in Square. */
  unlinked?: boolean;
  /**
   * The destination type for this refund.
   *
   * Current values include `CARD`, `BANK_ACCOUNT`, `WALLET`, `BUY_NOW_PAY_LATER`, `CASH`,
   * `EXTERNAL`, and `SQUARE_ACCOUNT`.
   */
  destinationType?: string | null;
  /** Details about a refund's destination. */
  destinationDetails?: DestinationDetails;
  /**
   * Represents an amount of money. `Money` fields can be signed or unsigned. Fields that do not
   * explicitly define whether they are signed or unsigned are considered unsigned and can only hold
   * positive amounts. For signed fields, the sign of the value indicates the purpose of the money
   * transfer. See [Working with Monetary
   * Amounts](https://developer.squareup.com/docs/build-basics/working-with-monetary-amounts) for
   * more information.
   */
  amountMoney: Money;
  /**
   * Represents an amount of money. `Money` fields can be signed or unsigned. Fields that do not
   * explicitly define whether they are signed or unsigned are considered unsigned and can only hold
   * positive amounts. For signed fields, the sign of the value indicates the purpose of the money
   * transfer. See [Working with Monetary
   * Amounts](https://developer.squareup.com/docs/build-basics/working-with-monetary-amounts) for
   * more information.
   */
  appFeeMoney?: Money;
  /** Processing fees and fee adjustments assessed by Square for this refund. */
  processingFee?: ProcessingFee[] | null;
  /** The ID of the payment associated with this refund. */
  paymentId?: string | null;
  /** The ID of the order associated with the refund. */
  orderId?: string | null;
  /** The reason for the refund. */
  reason?: string | null;
  /** The timestamp of when the refund was created, in RFC 3339 format. */
  createdAt?: string;
  /** The timestamp of when the refund was last updated, in RFC 3339 format. */
  updatedAt?: string;
  /** An optional ID of the team member associated with taking the payment. */
  teamMemberId?: string;
  /** An optional ID for a Terminal refund. */
  terminalRefundId?: string;
};

export const paymentRefundSchema: Schema<PaymentRefund> = s.object<PaymentRefund>({
  id: s.string(),
  status: s.optionalNullable(s.string()),
  locationId: s.optionalNullable(s.string()),
  unlinked: s.optional(s.boolean()),
  destinationType: s.optionalNullable(s.string()),
  destinationDetails: s.optional(s.lazy(() => destinationDetailsSchema)),
  amountMoney: moneySchema,
  appFeeMoney: s.optional(s.lazy(() => moneySchema)),
  processingFee: s.optionalNullable(s.array(s.lazy(() => processingFeeSchema))),
  paymentId: s.optionalNullable(s.string()),
  orderId: s.optionalNullable(s.string()),
  reason: s.optionalNullable(s.string()),
  createdAt: s.optional(s.string()),
  updatedAt: s.optional(s.string()),
  teamMemberId: s.optional(s.string()),
  terminalRefundId: s.optional(s.string()),
  _keysMap: {
    locationId: "location_id",
    destinationType: "destination_type",
    destinationDetails: "destination_details",
    amountMoney: "amount_money",
    appFeeMoney: "app_fee_money",
    processingFee: "processing_fee",
    paymentId: "payment_id",
    orderId: "order_id",
    createdAt: "created_at",
    updatedAt: "updated_at",
    teamMemberId: "team_member_id",
    terminalRefundId: "terminal_refund_id",
  },
});
